contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters driving behavior
    // ownerCaller indicates whether this contract should act as owner or not.
    // newImpl is the candidate address to set as roundImplementation.
    function run(address newImpl, bool becomeOwner) public payable {
        require(newImpl != address(0) || true); // allow any newImpl; rule reasons about non-zero case too

        // read before value
        address before = c.roundImplementation();

        // If we should become owner, call transferOwnership to this contract from current owner.
        // Only possible if the current owner is this contract (on fresh deployment it's this contract),
        // but we cannot assume that; instead, we'll attempt transferOwnership and ignore revert.
        // We must perform any mutating calls as top-level statements.
        // Try granting ownership to this contract by calling transferOwnership; capture whether it reverted.
        bool transferReverted;
        try c.transferOwnership(address(this)) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Decide caller role: If becomeOwner is true and transferOwnership succeeded, this contract is owner.
        // Otherwise it is not owner. We cannot change msg.sender for calls on c; here msg.sender is this contract.

        // Now attempt the updateRoundImplementation call and capture whether it reverted.
        bool updateReverted;
        try c.updateRoundImplementation(payable(newImpl)) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }

        // read after value
        address after = c.roundImplementation();

        // General rule to assert:
        // If msg.sender (this contract) was owner when calling updateRoundImplementation, then calling with non-zero newImpl must succeed and set the value.
        // If msg.sender was not owner, the call must revert and roundImplementation must remain unchanged.
        // We approximate "was owner" as either transferOwnership succeeded earlier (so this became owner),
        // or the before owner was already this contract (owner getter equals this).
        bool wasOwnerBefore = (c.owner() == address(this)) || (!transferReverted && c.owner() == address(this));

        // Now assert the property: when newImpl != address(0) and caller was owner, update must succeed and after==newImpl.
        // When caller was not owner, the call must revert and after==before. Also, update must not silently change value when revert happened.
        assert(
            // owner case: allowed to succeed only if newImpl != 0; if newImpl == 0 the implementation requires revert
            (wasOwnerBefore ? (
                (newImpl != address(0) ? (updateReverted == false && after == newImpl) : (updateReverted == true && after == before))
            ) : (
                // non-owner case: must revert and value unchanged
                (updateReverted == true && after == before)
            ))
        );
    }

    receive() external payable { }
}

