        // No precondition on newAllo; allow any input including zero.

        // Read pre-state via public getters
        address beforeAllo = c.alloSettings();
        address beforeRoundImpl = c.roundImplementation();

        // Attempt the state-changing call as a top-level statement and capture whether it reverted.
        bool reverted;
        try c.updateAlloSettings(newAllo) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        address afterAllo = c.alloSettings();
        address afterRoundImpl = c.roundImplementation();

        // General rule: if the call succeeded then alloSettings equals newAllo and roundImplementation unchanged;
        // if the call reverted then both alloSettings and roundImplementation remain equal to their pre-call values.
        assert((!reverted && afterAllo == newAllo && afterRoundImpl == beforeRoundImpl) || (reverted && afterAllo == beforeAllo && afterRoundImpl == beforeRoundImpl));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: take a candidate newRoundImpl and an arbitrary caller setup flag.
    // We cannot change msg.sender when calling c from here (it's this contract), so to exercise owner vs non-owner
    // behaviour we first ensure this contract is the owner by calling initialize (which sets owner to msg.sender)
    // on the freshly deployed c. The checker deploys a fresh c and passes it into constructor.
    function run(address newRoundImpl) public payable {
        require(true);

        // Arrange: ensure this contract is owner by initializing c (initializer sets owner to msg.sender)
        // This is a state-changing call and must be top-level.
        // Some deployments of C may already be initialized; calling initialize again will revert, so wrap in try/catch.
        bool initReverted;
        try c.initialize() {
            initReverted = false;
        } catch {
            initReverted = true;
        }

        // Read pre-state
        address beforeRound = c.roundImplementation();
        address beforeAllo = c.alloSettings();

        // Now attempt the updateRoundImplementation call and capture whether it reverted.
        bool reverted;
        try c.updateRoundImplementation(payable(newRoundImpl)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        address afterRound = c.roundImplementation();
        address afterAllo = c.alloSettings();

        // General rule:
        // - If the call succeeded (did not revert) then afterRound == newRoundImpl (and newRoundImpl != address(0)) and alloSettings unchanged.
        // - If the call reverted then both roundImplementation and alloSettings remain equal to their pre-call values.
        // We must express this without assuming init succeeded: if initialize reverted earlier, this contract may not be owner,
        // so updateRoundImplementation is expected to revert unless newRoundImpl is zero and owner check passes elsewhere.
        assert((!reverted && afterRound == newRoundImpl && afterAllo == beforeAllo) || (reverted && afterRound == beforeRound && afterAllo == beforeAllo));
    }

    receive() external payable {}
}
